      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "A estrutura de análise de risco descrita na fonte compreende caracterização do projeto, identificação de perigos, diagnóstico objetivo dos riscos e implantação de medidas mitigadoras por meio de programa de gestão de risco para reduzir acidentes ou garantir operações seguras.",
          "trechos": [
            "E6aaa78ea939ac3f7:0:693"
          ],
          "condicoes": [
            "Apresentado como explicação geral de gestão de risco."
          ],
